verification_command:
$ErrorActionPreference='Stop'
$packet='docs/testing/performance/0.74/local-runs/root-guard-attribution-20261015'
$m=Get-Content -Raw -LiteralPath "$packet/manifest.json" | ConvertFrom-Json
$names=@($m.captures.file)
if($names.Count -ne 49 -or @($names|Sort-Object -Unique).Count -ne 49){throw 'capture inventory'}
$disk=@(Get-ChildItem -LiteralPath $packet -File -Filter '*.log'|Select-Object -ExpandProperty Name)
if(@(Compare-Object $names $disk).Count -ne 0){throw 'unlisted raw log'}
foreach($a in @($m.captures)+@($m.extra_artifacts)){
 if((Split-Path -Leaf $a.file) -cne $a.file){throw 'artifact basename'}
 $f=Get-Item -LiteralPath "$packet/$($a.file)"
 if($f.Length -ne $a.bytes -or (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -cne $a.sha256){throw "artifact changed: $($a.file)"}
}
foreach($f in $m.frozen_files){if((Get-FileHash -LiteralPath $f.path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $f.sha256){throw 'frozen input'}}
if((git rev-parse "$($m.source_commit)^{tree}") -cne $m.source_tree){throw 'source tree'}
foreach($f in $m.source_files){if((git rev-parse "$($m.source_commit):$($f.path)") -cne $f.git_blob){throw 'source blob'}}
if((git rev-parse "$($m.source_commit):docs/testing/gated-test-registry.toml") -cne $m.registry_blob){throw 'registry blob'}
foreach($link in $m.commit_chain){if((git rev-parse "$($link.commit)^") -cne $link.parent){throw 'commit chain'}}
$changed=@(git diff --name-only $m.baseline_commit $m.source_commit -- tools)
if($changed.Count -ne 5 -or @(Compare-Object $changed @($m.source_files.path)).Count -ne 0){throw 'source inventory'}
if(@(git diff --name-only $m.baseline_commit $m.source_commit -- crates Cargo.toml Cargo.lock .github).Count -ne 0){throw 'product/dependency/workflow drift'}
$data=Get-Content -Raw -LiteralPath "$packet/retained-source-rewrites.json"|ConvertFrom-Json
foreach($source in $data.sources){
 $old=(git show "$($m.baseline_commit):$($source.path)") -join "`n"
 $new=(git show "$($m.source_commit):$($source.path)") -join "`n"
 foreach($r in $source.rewrites){
  if([regex]::Matches($old,[regex]::Escape($r.before)).Count -ne 1){throw 'rewrite uniqueness'}
  $old=$old.Replace($r.before,$r.after)
 }
 if($old.TrimEnd() -cne $new.TrimEnd()){throw "unregistered source change: $($source.path)"}
}
$unchanged=@('tools/long-run-supervisor-074/Cargo.toml','tools/long-run-supervisor-074/src/bin/diagnostic_signer_root_probe.rs','tools/long-run-supervisor-074/src/diagnostic_signer_owned_root_exec.rs','tools/long-run-supervisor-074/src/diagnostic_signer_owned_root_handoff.rs','tools/long-run-supervisor-074/src/diagnostic_signer_owned_root_loss.rs','tools/long-run-supervisor-074/src/diagnostic_signer_owned_root_isolation.rs','tools/long-run-supervisor-074/src/diagnostic_signer_isolation_core.rs','docs/testing/performance/0.74/local-runs/msrv-tooling-trace-cleanup-20261015/after-trace-process-timeout.log')
foreach($path in $unchanged){if((git rev-parse "$($m.baseline_commit):$path") -cne (git rev-parse "$($m.source_commit):$path")){throw "original source/negative changed: $path"}}
$oldRegistry=(git show "$($m.baseline_commit):docs/testing/gated-test-registry.toml") -join "`n"
$newRegistry=(git show "$($m.source_commit):docs/testing/gated-test-registry.toml") -join "`n"
$entry='[[gate]]'+"`n"+'id = "cfg.hydracache-long-run-supervisor-074.diagnostic-signer-root-guard"'
$start=$newRegistry.IndexOf($entry)
if($start -lt 0){throw 'new registry entry missing'}
$next=$newRegistry.IndexOf('[[gate]]',$start+8)
if($next -lt 0 -or $newRegistry.Remove($start,$next-$start).TrimEnd() -cne $oldRegistry.TrimEnd()){throw 'existing registry entries changed'}
foreach($spec in @('attribution-rewrite.json','hash-attribution-rewrites.json')){
 $overlay=Get-Content -Raw -LiteralPath "$packet/$spec"|ConvertFrom-Json
 $rewrites=if($overlay.rewrites){@($overlay.rewrites)}else{@($overlay)}
 foreach($r in $rewrites){$base=(git show "$($m.baseline_commit):$($r.path)") -join "`n"; if([regex]::Matches($base,[regex]::Escape($r.before)).Count -ne 1){throw 'overlay baseline'}}
}
function Assert-Totals($file,$passed,$failed){
 $text=Get-Content -Raw -LiteralPath "$packet/$file"
 $testTotals=[regex]::Matches($text,'test result: (?:ok|FAILED)\. (\d+) passed; (\d+) failed; (\d+) ignored;')
 $p=0;$f=0
 foreach($match in $testTotals){$p+=[int]$match.Groups[1].Value;$f+=[int]$match.Groups[2].Value;if([int]$match.Groups[3].Value -ne 0){throw 'unreported ignored tests'}}
 if($testTotals.Count -eq 0 -or $p -ne $passed -or $f -ne $failed){throw "test totals: $file"}
}
Assert-Totals 'baseline-process.log' 67 0
Assert-Totals 'guard-test-first-red.log' 2 1
foreach($file in @('guard-linux-current.log','guard-linux-msrv.log','final-linux-1.88.0-guard.log','final-linux-1.94.0-guard.log')){Assert-Totals $file 9 0}
foreach($file in @('hash-test-first-current.log','hash-test-first-msrv.log','final-linux-1.88.0-hash.log','final-linux-1.94.0-hash.log')){Assert-Totals $file 1 0}
foreach($file in @('attribution-stage-1.log','attribution-stage-2.log','hash-attribution-1.log','hash-attribution-3.log')){Assert-Totals $file 66 1}
Assert-Totals 'hash-attribution-2.log' 46 1
foreach($file in @('candidate-process-1.log','candidate-process-2.log','postcommit-process.log')){
 Assert-Totals $file 68 0
 $text=Get-Content -Raw -LiteralPath "$packet/$file"
 foreach($row in @(@('^normal_root_handoff mode=',25),@('^normal_root_transfer kind=',14),@('^normal_root_send_window kind=',6))){if([regex]::Matches($text,'(?m)'+$row[0]).Count -ne $row[1]){throw 'canonical mode coverage'}}
 if($text.Contains('root_handoff_attribution')){throw 'instrumentation promoted to canonical'}
}
Assert-Totals 'candidate-process-msrv.log' 68 0
$msrv=Get-Content -Raw -LiteralPath "$packet/candidate-process-msrv.log"
if(-not $msrv.Contains('extra_libm_root_handoff_modes=25 refused=true') -or $msrv.Contains('normal_root_handoff mode=good')){throw 'MSRV refusal promoted'}
Assert-Totals 'performance-contracts-before-registration.log' 165 0
Assert-Totals 'performance-contract-tests.log' 165 0
Assert-Totals 'gate-registry-tests.log' 6 0
$failed=@('guard-test-first-red.log','attribution-stage-1.log','attribution-stage-2.log','hash-attribution-1.log','hash-attribution-2.log','hash-attribution-3.log','gate-registry-before-registration.log')
foreach($c in $m.captures){
 if($failed -contains $c.file){if($c.exit_code -ne 1 -or $c.gate_expected_exit -ne 0){throw 'negative reclassified'}}
 elseif($c.file -ceq 'require-ship.log'){if($c.exit_code -ne 1 -or $c.gate_expected_exit -ne 1){throw 'closed admission reclassified'}}
 elseif($c.exit_code -ne 0 -or $c.gate_expected_exit -ne 0){throw 'unexpected capture status'}
}
if((Get-Content -Raw -LiteralPath "$packet/gate-registry.log") -notmatch '176 discovered gates, all registered'){throw 'registry final count'}
Write-Output 'Verified 49 captures, 5 extra artifacts, source/tree/5 blobs/registry/commit chain and frozen inputs. Registered source rewrites preserve other existing code; one additive registry entry preserves all old entries.'
Write-Output 'Verified test counts and canonical 25/14/6 modes; MSRV remains extra-libm refusal. Seven negative captures stay exit1/expected-gate0, including a real attribution timeout, unexpected SCM_RIGHTS unit EAGAIN and missing registry entry. Require-ship alone is an expected refusal.'
Write-Output 'Unsigned consistency only, not execution attestation or a product performance/robustness/server-admission claim. Historical timeout instruction and SCM_RIGHTS writer lifetime remain open.'
